"""Bounded socket multiplexing over an owned container's stdin/stdout.

The same reviewed standard-library source runs on both ends. No host port or
container network is needed, including with Docker Desktop's Linux VM.
"""
WIRE_SOURCE = '\nimport json, os, queue, socket, struct, sys, threading\n\nclass Wire:\n    HEADER = struct.Struct(\'!IBI\')\n    OPEN, DATA, END, HELLO, CREDIT = 1, 2, 3, 4, 5\n    MAX_STREAMS, MAX_DATA = 64, 65536\n\n    def __init__(self, reader, writer, incoming, first=1):\n        self.reader, self.writer, self.incoming = reader, writer, incoming\n        self.next_id, self.first = first, first\n        self.streams = {}; self.guard = threading.RLock(); self.output = threading.Lock()\n        self.closed = threading.Event(); self.ready = threading.Event()\n        threading.Thread(target=self.receive, daemon=True, name=\'office-wire-reader\').start()\n        self.send(0, self.HELLO, b\'{"protocol":1}\')\n\n    def send(self, identity, kind, data=b\'\'):\n        if self.closed.is_set(): raise OSError(\'document channel closed\')\n        if len(data) > self.MAX_DATA: raise ValueError(\'document frame too large\')\n        with self.output:\n            packet=memoryview(self.HEADER.pack(identity, kind, len(data)) + data)\n            while packet:\n                written=self.writer.write(packet)\n                if not written:raise OSError(\'document channel write failed\')\n                packet=packet[written:]\n            self.writer.flush()\n\n    def exact(self, length):\n        chunks=[]\n        while length:\n            block=self.reader.read(length)\n            if not block: raise EOFError()\n            chunks.append(block);length-=len(block)\n        return b\'\'.join(chunks)\n\n    def attach(self, identity, connection, notify=None):\n        with self.guard:\n            if len(self.streams)>=self.MAX_STREAMS or identity in self.streams:\n                connection.close();raise OSError(\'document channel busy\')\n            record=(connection,queue.Queue(9),threading.BoundedSemaphore(8),threading.Event(),[False,False]);self.streams[identity]=record\n        if notify is not None:self.send(identity,self.OPEN,json.dumps({\'role\':notify}).encode())\n        def upload():\n            try:\n                while not self.closed.is_set() and not record[3].is_set():\n                    if not record[2].acquire(timeout=.5):continue\n                    data=connection.recv(self.MAX_DATA)\n                    if not data:break\n                    self.send(identity,self.DATA,data)\n            except (OSError,ValueError):pass\n            finally:\n                try:self.send(identity,self.END)\n                except (OSError,ValueError):pass\n                self.finished(identity,record,0)\n        def download():\n            try:\n                while not self.closed.is_set():\n                    data=record[1].get()\n                    if data is None:break\n                    connection.sendall(data)\n                    self.send(identity,self.CREDIT)\n            except OSError:pass\n            finally:\n                try:connection.shutdown(socket.SHUT_WR)\n                except OSError:pass\n                self.finished(identity,record,1)\n        threading.Thread(target=upload,daemon=True,name=\'office-wire-upload\').start()\n        threading.Thread(target=download,daemon=True,name=\'office-wire-download\').start()\n\n    def finished(self,identity,record,direction):\n        with self.guard:\n            record[4][direction]=True\n            complete=all(record[4])\n        if complete:self.drop(identity,record)\n\n    def drop(self,identity,expected=None):\n        with self.guard:\n            record=self.streams.get(identity)\n            if record is None or expected is not None and record is not expected:return\n            self.streams.pop(identity,None)\n        record[3].set()\n        try:record[1].put_nowait(None)\n        except queue.Full:pass\n        try:record[0].shutdown(socket.SHUT_RDWR)\n        except OSError:pass\n        record[0].close()\n\n    def open(self, role=\'engine\'):\n        if not self.ready.wait(10):raise OSError(\'document channel handshake timed out\')\n        with self.guard:\n            if self.closed.is_set() or len(self.streams)>=self.MAX_STREAMS:raise OSError(\'document channel unavailable\')\n            identity=self.next_id;self.next_id+=2\n            if identity>0xffffffff:raise OSError(\'document channel needs reconnecting\')\n        application,transport=socket.socketpair()\n        try:\n            self.attach(identity,transport,role)\n        except BaseException:\n            self.drop(identity);application.close();raise\n        return application\n\n    def accept(self,connection,role=\'callback\'):\n        with self.guard:identity=self.next_id;self.next_id+=2\n        try:\n            self.attach(identity,connection,role)\n        except (OSError,ValueError):self.drop(identity);connection.close()\n\n    def receive(self):\n        try:\n            while not self.closed.is_set():\n                identity,kind,length=self.HEADER.unpack(self.exact(self.HEADER.size))\n                if length>self.MAX_DATA:raise ValueError(\'oversized document frame\')\n                data=self.exact(length)\n                if kind==self.HELLO:\n                    if identity or json.loads(data).get(\'protocol\')!=1:raise ValueError(\'document protocol mismatch\')\n                    self.ready.set();continue\n                if not identity or kind not in (self.OPEN,self.DATA,self.END,self.CREDIT):raise ValueError(\'invalid document frame\')\n                if kind==self.OPEN:\n                    if identity%2==self.first%2 or length>1024:raise ValueError(\'invalid document stream\')\n                    try:\n                        connection=self.incoming(json.loads(data).get(\'role\'))\n                        self.attach(identity,connection)\n                    except (OSError,ValueError):self.send(identity,self.END)\n                    continue\n                with self.guard:record=self.streams.get(identity)\n                if record is None:continue\n                if kind==self.CREDIT:\n                    if length:raise ValueError(\'invalid document credit\')\n                    record[2].release();continue\n                try:record[1].put_nowait(data if kind==self.DATA else None)\n                except queue.Full:\n                    self.drop(identity)\n                    self.send(identity,self.END)\n        except (OSError,ValueError,EOFError,struct.error):pass\n        finally:self.close()\n\n    def close(self):\n        if self.closed.is_set():return\n        self.closed.set();self.ready.set()\n        with self.guard:identities=list(self.streams)\n        for identity in identities:self.drop(identity)\n\ndef serve_container():\n    listener=socket.socket();listener.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)\n    listener.bind((\'127.0.0.1\',7900));listener.listen(32);listener.settimeout(1)\n    def incoming(role):\n        if role!=\'engine\':raise ValueError(\'unsupported container target\')\n        connection=socket.create_connection((\'127.0.0.1\',80),timeout=30)\n        connection.settimeout(None);return connection\n    channel=Wire(sys.stdin.buffer,sys.stdout.buffer,incoming,first=2)\n    try:\n        while not channel.closed.is_set():\n            try:connection,_=listener.accept()\n            except socket.timeout:continue\n            channel.accept(connection)\n    finally:listener.close();channel.close()\n'
_namespace = {}
exec(compile(WIRE_SOURCE, '<crb-document-wire>', 'exec'), _namespace)
Wire = _namespace['Wire']
